/* Each word sits in an inline-block mask (overflow: clip, so view timelines keep working)
   with a little room below for descenders. The word starts 125% low and rises into place:
   on load with a time-based ease, or scrubbed by the word's own view timeline as it enters,
   over a fixed 240px of scroll so lines low in the first screen still finish. */
.leome-and-partners-word-reveal-mask {
  display: inline-block;
  overflow: clip;
  vertical-align: top;
  padding-bottom: 0.14em;
  margin-bottom: -0.14em;
  view-timeline-name: --leome-and-partners-word;
}

.leome-and-partners-word-reveal-word {
  display: inline-block;
}

@media (prefers-reduced-motion: no-preference) {
  .leome-and-partners-word-reveal[data-trigger="load"] .leome-and-partners-word-reveal-word {
    animation: leome-and-partners-word-reveal-rise 1s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  @supports (animation-timeline: view()) {
    .leome-and-partners-word-reveal[data-trigger="view"] .leome-and-partners-word-reveal-word {
      animation: leome-and-partners-word-reveal-rise linear both;
      animation-timing-function: cubic-bezier(0.33, 1, 0.68, 1);
      animation-timeline: --leome-and-partners-word;
      animation-range: entry 0% entry 240px;
    }
  }
}

@keyframes leome-and-partners-word-reveal-rise {
  from {
    transform: translateY(125%);
  }
  to {
    transform: none;
  }
}

import { Fragment } from "react";
import { cn } from "@foundry/foundry-utils";
import "./leome-and-partners-word-reveal.css";

export interface LeomeAndPartnersWordRevealProps {
  /** the text; it is split on spaces and every word rises out of its own mask */
  text: string;
  /**
   * "load": the words rise once as the page loads (use it in the first screen).
   * "view": the words rise as they scroll into view; words on one line move together and
   * the next line follows, which reads as the original's line-by-line reveal.
   */
  trigger?: "load" | "view";
  /** load only: seconds before the first word starts */
  delay?: number;
  /** load only: seconds between one word and the next */
  stagger?: number;
  className?: string;
}

/**
 * Inline text whose words rise out of clipping masks. Put it inside a heading or paragraph;
 * it takes the font, size and colour of its parent. Without scroll-timeline support, or with
 * reduced motion, the text simply stands in place.
 */
export function LeomeAndPartnersWordReveal({
  text,
  trigger = "view",
  delay = 0,
  stagger = 0.06,
  className,
}: LeomeAndPartnersWordRevealProps) {
  const words = text.split(/\s+/).filter(Boolean);
  return (
    <span className={cn("leome-and-partners-word-reveal", className)} data-trigger={trigger}>
      {words.map((word, i) => (
        <Fragment key={i}>
          <span className="leome-and-partners-word-reveal-mask">
            <span
              className="leome-and-partners-word-reveal-word"
              style={trigger === "load" ? { animationDelay: `${(delay + i * stagger).toFixed(2)}s` } : undefined}
            >
              {word}
            </span>
          </span>
          {i < words.length - 1 && " "}
        </Fragment>
      ))}
    </span>
  );
}
